"""Render verified audit evidence into a standalone HTML report."""
import argparse, json
from pathlib import Path
from html import escape

def render(a):
    e=a['evidence']; trace=a['trace']; findings=a['findings']; n=len(trace); ai=sum(t['source']=='AI-selected' for t in trace)
    h=lambda v:escape(str(v),quote=True)
    rows=''.join('<tr>'+''.join(f'<td>{h(f[k])}</td>' for k in ('row','column','check','severity','detail'))+'</tr>' for f in findings)
    checks=''.join(f'<div class="check"><span>{h(t["tool"].removeprefix("check_").replace("_"," ").title())}<small>{h(t["source"])}</small></span><b>{h(t["exceptions"])}</b></div>' for t in trace)
    rec='; '.join(f['detail'] for f in findings if f['check']=='reconciliation') or 'No reconciliation exceptions detected.'
    return f'''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>DataSentry AI | Audit</title><style>
    *{{box-sizing:border-box}}body{{margin:0;background:#f0f4f8;color:#172b42;font:16px system-ui,sans-serif}}main{{max-width:1180px;margin:auto;padding:32px}}header{{background:#102a43;color:white;padding:28px;border-radius:16px}}h1{{margin:0;font-size:32px}}h2{{font-size:19px}}small{{display:block;color:#64748b;font-size:12px}}header small{{color:#b8d3e8}}.metrics{{display:grid;grid-template-columns:repeat(auto-fit,minmax(150px,1fr));gap:14px;margin:20px 0}}.metric,section{{background:white;border:1px solid #dbe4ed;border-radius:12px;padding:20px}}.metric b{{display:block;font-size:32px;margin-top:8px}}.split{{display:grid;grid-template-columns:repeat(auto-fit,minmax(300px,1fr));gap:16px}}.check{{display:flex;justify-content:space-between;border-bottom:1px solid #e5eaf0;padding:8px 0}}section{{margin-bottom:16px}}table{{border-collapse:collapse;width:100%;font-size:14px}}td,th{{padding:10px;text-align:left;border-bottom:1px solid #e5eaf0}}th{{background:#eaf1f7}}.scroll{{overflow:auto}}.status{{color:#a33c24;font-weight:700}}footer{{font-size:13px;color:#64748b}}</style><main><header><small>OPEN-SOURCE DATA QUALITY · AUDIT REPORT</small><h1>DataSentry AI</h1><p>Verified Python evidence · Local model: {h(a['model'])}</p></header><div class="metrics"><div class="metric">Rows scanned<b>{h(e['rows_scanned'])}</b></div><div class="metric">Exceptions<b>{h(e['exception_count'])}</b></div><div class="metric">AI-selected checks<b>{ai}/{n}</b></div><div class="metric">Coverage fallback<b>{n-ai}</b></div></div><div class="split"><section><h2>Validation execution</h2>{checks}</section><section><h2>Reporting readiness</h2><p class="status">{'Review required' if findings else 'No exceptions detected by configured checks'}</p><h2>Financial reconciliation</h2><p>{h(rec)}</p><p>Investigate exceptions against source records before publishing totals. No source data was corrected.</p><small>Summary generated from verified findings, not model-generated counts.</small></section></div><section><h2>Exception register</h2><div class="scroll"><table><thead><tr><th>Row</th><th>Column</th><th>Check</th><th>Severity</th><th>Evidence</th></tr></thead><tbody>{rows}</tbody></table></div></section><footer>Configured sales-schema checks only. Exceptions may overlap within a row. Unverified AI commentary is excluded from this report.</footer></main></html>'''

def main():
    p=argparse.ArgumentParser(description=__doc__); p.add_argument('--input',default='outputs/agent_audit.json'); p.add_argument('--output',default='outputs/audit_report.html'); a=p.parse_args(); dest=Path(a.output); dest.parent.mkdir(parents=True,exist_ok=True); dest.write_text(render(json.loads(Path(a.input).read_text(encoding='utf-8'))),encoding='utf-8'); print(f'Report generated: {dest}')
if __name__=='__main__': main()
